{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 응답 시간을 줄이기 위해 병목 원인에 맞는 개선 방법을 선택한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리 응답이 느렸던 상황.",
          "task": "조회 지연의 원인에 적합한 개선 방법을 정해야 했던 과제.",
          "action": "실행 계획이나 조회 구조에서 확인한 병목 특성을 기준으로 개선 방법을 선택한 판단을 설명한다.",
          "result": "개선 전후의 측정 조건과 응답 시간 수치는 꼬리질문에서 확인."
        },
        "expectedEvidence": [
          "개선 방법을 선택하는 기준으로 삼은 실행 계획이나 조회 구조의 구체적인 병목 특성",
          "선택한 개선 방법이 해당 병목을 줄이는 데 적합하다고 판단한 이유"
        ]
      },
      "question": "운영 화면의 신고 목록 조회 쿼리를 개선하셨다고 했는데요. 응답 시간을 줄이기 위해 개선 방법은 어떤 기준으로 정하셨나요?",
      "answerTip": "당시 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획이나 조회 구조에서 확인한 구체적인 병목 특성을 개선 방법의 선택 기준으로 설명한다.",
            "선택한 인덱스나 쿼리 수정 등의 방법이 해당 병목을 줄이는 이유를 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "병목을 줄이려는 개선 방법의 선택 기준은 제시하지만, 당시 확인한 실행 계획이나 조회 구조의 설명이 부족하다.",
            "선택한 방법과 병목의 관련성은 설명하지만 해당 방법이 적합한 이유가 포괄적이다."
          ]
        },
        "poor": {
          "criteria": [
            "수행한 수정이나 응답 시간의 변화만 나열하고 개선 방법의 선택 기준은 설명하지 않는다.",
            "인덱스나 캐시가 일반적으로 빠르다는 설명에 머물러 당시 병목과 개선 방법을 연결하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "운영 오류의 반복을 막기 위해 당장의 복구 조치와 재발 방지 방안을 구분해 세운 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 후 알림 중복 발송 오류가 발생했던 상황.",
          "task": "진행 중인 오류의 복구와 같은 오류의 재발 방지를 구분해 대책을 세워야 했던 과제.",
          "action": "로그로 파악한 발생 원인을 바탕으로 즉시 해소할 문제와 반복을 막아야 할 조건을 구분한 기준을 설명한다.",
          "result": "복구 여부와 재발 방지 방안의 적용 결과는 꼬리질문에서 확인."
        },
        "expectedEvidence": [
          "진행 중인 중복 발송을 해소하는 목적과 같은 장애의 반복 조건을 없애는 목적을 구분한 기준",
          "로그로 파악한 오류 발생 원인이 복구 조치와 재발 방지 방안의 구분에 연결된 이유"
        ]
      },
      "question": "배포 후 알림 중복 발송 오류를 수정하셨다고 했는데요. 같은 장애가 반복되지 않도록 복구 조치와 재발 방지 방안을 나눈 기준은 무엇이었나요?",
      "answerTip": "당시 생각을 차분하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진행 중인 중복 발송의 해소와 반복 조건의 제거를 구분해 조치를 세운 기준을 설명한다.",
            "로그에서 확인한 오류 발생 원인을 구체적으로 언급하며 각 조치의 목적을 구분한 이유와 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "즉시 복구와 재발 방지의 목적 차이는 설명하지만 당시 조치를 구분한 기준이 포괄적이다.",
            "오류 발생 원인을 언급하지만 그 원인이 조치 구분에 미친 영향은 충분히 설명하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "수정 작업만 나열하고 복구 조치와 재발 방지 방안을 구분한 기준을 설명하지 않는다.",
            "장애 원인과 관련 없는 일반적인 점검 방안만 제시해 조치 구분의 이유를 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "개발 담당자와 구현 범위를 합의할 수 있도록 요청의 목적, 포함·제외 범위, 우선순위와 예외 케이스를 요구사항 문서로 구체화한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 인터뷰 내용을 요구사항 정의서로 정리한 상황",
          "task": "개발 담당자와 합의할 수 있는 수준으로 요구사항과 구현 범위를 명확히 하는 일",
          "action": "요청의 목적에 따라 포함·제외 범위와 우선순위를 정하고, 예외 케이스를 문서에 구체화한 기준을 설명한다.",
          "result": "문서를 통한 범위 합의 여부는 꼬리질문에서 확인한다."
        },
        "expectedEvidence": [
          "요청의 목적을 바탕으로 포함할 요구사항과 제외할 요구사항을 구분한 문서화 기준",
          "요구사항의 우선순위를 정해 문서에 구체화한 기준",
          "구현 범위의 해석이 달라지지 않도록 예외 케이스를 명시한 기준"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성하셨네요. 개발 담당자와 범위를 합의하도록 요구사항을 문서로 구체화한 기준은 무엇이었나요?",
      "answerTip": "본인이 했던 일을 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 요구사항을 예로 들어 요청 목적에 따른 포함·제외 범위와 우선순위의 문서화 기준을 설명한다.",
            "예외 케이스를 어느 수준까지 명시했는지 설명하며, 그 기준이 개발 담당자와 구현 범위를 같은 의미로 이해하는 데 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "포함·제외 범위, 우선순위 또는 예외 케이스를 문서에 구체화한 기준은 제시하지만 일부 요소가 빠져 있다.",
            "목적이나 중요도를 기준으로 정리했다고 설명하지만 실제 요구사항에 적용한 내용이나 범위 합의와의 연결이 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰 내용을 옮겼다거나 문서 양식을 채웠다는 설명에 그쳐 요구사항을 구체화한 기준이 드러나지 않는다.",
            "화면 개선 성과나 인터뷰 수행 사실만 설명하고 포함·제외 범위, 우선순위, 예외 케이스의 문서화 기준을 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "개발자와 디자이너가 추가 해석 없이 구현할 수 있도록 화면 흐름, 상태 변화, 예외 상황과 안내 문구를 화면설계서에 구체화한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 작성 상황",
          "task": "화면별 동작을 개발자와 디자이너가 같은 의미로 이해할 수 있게 명시하는 일",
          "action": "화면 간 연결과 상태 변화, 예외 상황별 동작 및 안내 문구를 구체화한 기준을 실제 설계 내용에 비추어 설명한다.",
          "result": "추가 질문이나 해석 차이가 있었는지는 꼬리질문에서 확인한다."
        },
        "expectedEvidence": [
          "화면 간 이동과 사용자 행동에 따른 상태 변화를 명시한 기준",
          "정상 흐름과 구분해 예외 상황별 화면 동작을 구체화한 기준",
          "화면 상태와 예외 상황에 맞는 안내 문구를 명시한 기준"
        ]
      },
      "question": "Figma로 화면설계서 28장을 작성하셨네요. 개발자와 디자이너가 되묻지 않고 구현하도록 화면별 동작을 구체화한 기준은 무엇이었나요?",
      "answerTip": "실제 작성했던 내용을 떠올리며 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 화면을 예로 들어 화면 이동과 사용자 행동에 따른 상태 변화를 어느 수준까지 명시했는지 기준을 설명한다.",
            "예외 상황별 동작과 안내 문구를 구체화한 기준이 드러나며, 구현 담당자가 동작을 임의로 해석하지 않도록 작성한 내용과 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "화면 흐름, 상태 변화, 예외 동작 또는 안내 문구를 구체화한 기준은 제시하지만 일부 요소가 빠져 있다.",
            "담당자가 이해할 수 있게 자세히 작성했다고 설명하지만 실제 화면에 적용한 기준은 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "작성 도구나 화면 수만 설명하고 화면별 동작을 구체화한 기준을 제시하지 못한다.",
            "시각적 배치나 디자인 취향만 설명하며 화면 흐름, 상태 변화, 예외 동작과 안내 문구를 구현 수준으로 명시한 기준이 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "환자와 처방 내용을 확인한 결과를 바탕으로 투약을 진행하거나 멈출 기준을 판단했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 전후 환자에게 처방에 따른 투약을 수행하던 상황",
          "task": "환자와 처방의 일치 여부를 확인해 안전하게 투약할 책임",
          "action": "환자 확인과 약물·용량·경로·시간의 확인 여부를 투약 진행 기준으로 삼고, 의심되거나 확인되지 않은 사항은 담당자 확인 전까지 투약을 보류하는 기준을 설명한다.",
          "result": "실제 확인 이후의 투약 진행 여부는 꼬리질문에서 확인한다."
        },
        "expectedEvidence": [
          "환자 확인과 약물·용량·경로·시간의 일치 여부를 투약 진행의 기준으로 제시한다.",
          "처방이 의심스럽거나 확인되지 않은 사항이 있으면 담당자에게 확인되기 전까지 투약을 보류한다는 판단 기준을 제시한다."
        ]
      },
      "question": "수술 전후 환자 투약·처치를 맡으셨다고 했는데요. 처방대로 안전하게 투약하려면 투약 진행 여부를 어떤 기준으로 판단하셨나요?",
      "answerTip": "본인이 했던 판단을 중심으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 투약 업무에서 환자와 약물·용량·경로·시간의 일치 여부를 확인해야 투약할 수 있다는 기준을 구체적으로 설명한다.",
            "처방이 의심스럽거나 확인되지 않으면 투약을 보류하고 담당자에게 확인한 뒤 진행한다는 기준을 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자와 처방을 확인한 뒤 투약한다는 기준은 제시하지만, 확인 항목이나 진행 가능 조건이 일부 불분명하다.",
            "의심스러운 처방은 담당자에게 확인한다고 설명하지만, 확인 전 투약 보류 여부가 명확하지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "투약 진행 여부의 판단 기준 없이 투약 업무를 했다는 설명에 그친다.",
            "환자나 처방 내용이 확인되지 않아도 투약하거나, 의심스러운 처방을 임의로 수정해 투약한다고 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태 변화가 기록과 인수인계로 이어지도록 전달할 내용을 정한 기준을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "활력징후와 통증을 관찰하고 기록하던 병동 간호 상황",
          "task": "환자 상태 변화를 정확히 남겨 담당 의사와 다음 근무자가 필요한 정보를 파악할 수 있게 할 책임",
          "action": "관찰 시점과 이전 상태 대비 변화를 바탕으로 전달 내용을 정하고, 이상 징후의 긴급성과 후속 관찰 필요성을 내용 선정 기준에 반영한다.",
          "result": "실제 보고와 인수인계에서 정보가 전달된 결과는 꼬리질문에서 확인한다."
        },
